    address VARCHAR NOT NULL,
    PRIMARY KEY (name)
);

CREATE TABLE Beer (
    name VARCHAR NOT NULL,
    brewer VARCHAR NOT NULL,
    PRIMARY KEY (name)
);

CREATE TABLE Drinker (
    name VARCHAR NOT NULL,
    address VARCHAR NOT NULL,
    PRIMARY KEY (name)
);

CREATE TABLE Frequents (
    drinker VARCHAR NOT NULL,
    bar VARCHAR NOT NULL,
    times_a_week SMALLINT NOT NULL,
    PRIMARY KEY (drinker, bar),
    FOREIGN KEY (drinker) REFERENCES Drinker(name),
    FOREIGN KEY (bar) REFERENCES Bar(name)
);

CREATE TABLE Serves (
    bar VARCHAR NOT NULL,
    beer VARCHAR NOT NULL,
    price DECIMAL(5,2) NOT NULL,
    PRIMARY KEY (bar, beer),
    FOREIGN KEY (bar) REFERENCES Bar(name),
    FOREIGN KEY (beer) REFERENCES Beer(name)
);

CREATE TABLE Likes (
    drinker VARCHAR NOT NULL,
    beer VARCHAR NOT NULL,
    PRIMARY KEY (drinker, beer),
    FOREIGN KEY (drinker) REFERENCES Drinker(name),
    FOREIGN KEY (beer) REFERENCES Beer(name)
);

counterexample:
INSERT INTO Bar(name, address) VALUES ('A','addr1');
INSERT INTO Bar(name, address) VALUES ('B','addr2');
INSERT INTO Beer(name, brewer) VALUES ('x','br1');
INSERT INTO Beer(name, brewer) VALUES ('y','br1');
INSERT INTO Serves(bar, beer, price) VALUES ('A','x', 3.50);
INSERT INTO Serves(bar, beer, price) VALUES ('B','x', 3.50);
INSERT INTO Serves(bar, beer, price) VALUES ('B','y', 4.00);

